// Array implementation of Queue\nclass Queue {
  constructor(capacity) {
    this.items = [];
    this.capacity = capacity;
    this.front = 0;
    this.rear = -1;
  }

  // Enqueue operation\n  enqueue(element) {
    if (this.isFull()) {
      console.log('Queue Overflow');
      return;
    }
    this.rear++;
    this.items[this.rear] = element;
    console.log(element + ' enqueued to queue');
  }

  // Dequeue operation\n  dequeue() {
    if (this.isEmpty()) {
      console.log('Queue Underflow');
      return null;
    }
    const element = this.items[this.front];
    this.front++;
    return element;
  }

  // Front operation\n  frontElement() {
    if (this.isEmpty()) {
      console.log('Queue is empty');
      return null;
    }
    return this.items[this.front];
  }

  // Rear operation\n  rearElement() {
    if (this.isEmpty()) {
      console.log('Queue is empty');
      return null;
    }
    return this.items[this.rear];
  }

  // Check if queue is empty\n  isEmpty() {
    return this.front > this.rear;
  }

  // Check if queue is full\n  isFull() {
    return this.rear === this.capacity - 1;
  }

  // Display queue\n  display() {
    console.log('Queue:', this.items.slice(this.front, this.rear + 1));
  }
}
\n// Example usage\nconst queue = new Queue(5);\nqueue.enqueue(10);\nqueue.enqueue(20);\nqueue.enqueue(30);\nqueue.display(); \n// Queue: [10, 20, 30]\nconsole.log('Dequeue:', queue.dequeue()); \n// 10\nqueue.display(); \n// Queue: [20, 30]\nconsole.log('Front:', queue.frontElement()); \n// 20\nconsole.log('Rear:', queue.rearElement()); \n// 30
